import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderExpiryTest {

    // 2026-03-01 12:00 Warsaw (CET, UTC+1) is 11:00 UTC; "now" is 2026-03-31 02:00 Warsaw.
    private static final Clock NOW = Clock.fixed(Instant.parse("2026-03-31T01:00:00Z"), ZoneOffset.UTC);

    private final OrderRepository repository = new OrderRepository();
    private final OrderService service = new OrderService(repository, NOW);

    private String place(Instant placedAt) {
        return service.place("c-1", Money.pln(1000), placedAt);
    }

    @Test
    void cancelsOnlyPlacedOrdersOlderThanThirtyDays() {
        String old = place(Instant.parse("2026-02-27T10:00:00Z"));   // 32 days ago
        String recent = place(Instant.parse("2026-03-05T10:00:00Z")); // 26 days ago
        String confirmed = place(Instant.parse("2026-02-01T10:00:00Z"));
        service.confirm(confirmed);

        assertEquals(1, service.expireStale());

        assertEquals("CANCELLED", service.summary(old).status());
        assertEquals("PLACED", service.summary(recent).status());
        assertEquals("CONFIRMED", service.summary(confirmed).status());
    }

    @Test
    void exactlyThirtyDaysIsNotExpired() {
        // Warsaw date 2026-03-01 is exactly 30 days before 2026-03-31.
        String edge = place(Instant.parse("2026-03-01T10:00:00Z"));

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", service.summary(edge).status());
    }

    @Test
    void secondRunCancelsNothingMore() {
        place(Instant.parse("2026-01-01T10:00:00Z"));

        assertEquals(1, service.expireStale());
        assertEquals(0, service.expireStale());
    }

    @Test
    void usesWarsawCalendarDays() {
        // 2026-03-01 00:30 Warsaw is 2026-02-28 23:30 UTC. Warsaw date is 2026-03-01: not yet expired.
        String edge = place(Instant.parse("2026-02-28T23:30:00Z"));

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", service.summary(edge).status());
    }
}
}
